    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, k = p.peak || 2;
      const ch = i.writes * growth, chDay = ch * 86400, upd = i.upd / 100;
      return { growth, k, ch, peakCh: ch * k, chDay, upd, upserts: ch * k * upd, gbDay: (chDay * i.rowKB) / 1e6, goldRows: ch * 0.2, q: i.queries / 60, tables: i.tables };
    },

